from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class PodStatus(SchemaObject):
    plane_type = SchemaField(name="planeType", not_null=True)
    pod_name = SchemaField(name="podName", not_null=True)
    pod_status = SchemaField(name="podStatus", not_null=True)
    capture_status = SchemaField(name="captureStatus", not_null=True)
    file_name = SchemaField(name="fileName", optional=True)
    file_size = SchemaField(name="fileSize", optional=True)
    failure_reason = SchemaField(name="failureReason", optional=True)

    def __init__(self, plane_type=None, pod_name=None, pod_status=None, capture_status=None, file_name=None, file_size=None,
                 failure_reason=None):
        self.plane_type = plane_type
        self.pod_name = pod_name
        self.pod_status = pod_status
        self.capture_status = capture_status
        self.file_name = file_name
        self.file_size = file_size
        self.failure_reason = failure_reason

        super(PodStatus, self).__init__()


class IPTrafficCaptureStatus(SchemaObject):
    service_status = SchemaField(name="serviceStatus", not_null=True)
    pod_status = SchemaField(name="podStatus", not_null=True, klass=PodStatus, many=True)
    start_time = SchemaField(name="startTime")
    failure_reason = SchemaField(name="failureReason", optional=True)

    def __init__(self, service_status=None, pod_status=None, start_time=None, failure_reason=None):
        self.service_status = service_status
        self.pod_status = pod_status
        self.start_time = start_time
        self.failure_reason = failure_reason

        super(IPTrafficCaptureStatus, self).__init__()
